def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n):
    for i in range(38):
        number = n + i
        s_val = sum_digits(number)
        if s_val % 11 == 0:
            return False # Condition failed: at least one S(n+i) is divisible by 11
    return True # Condition met: none of S(n+i) are divisible by 11

n = 1
while True:
    if check_n(n):
        print(f"Smallest n found: {n}")
        break
    n += 1

def S(n):
    return sum(int(digit) for digit in str(n))

# Check for multiples of 11 for small k
limit = 300
multiples_of_11 = []
for k in range(1, limit + 1):
    s_k = S(k)
    if s_k % 11 == 0:
        multiples_of_11.append((k, s_k))

print("k where S(k) is a multiple of 11 (up to 300):")
print(multiples_of_11)

# Check S(k) vs S(k+1) behavior around carries (e.g., 9, 19, 99)
print("\nTesting k near carries:")
test_k_list = [9, 19, 29, 99, 109, 199]
for k in test_k_list:
    print(f"k={k}: S(k)={S(k)}, S(k+1)={S(k+1)}")

def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

n = 999981
check_failed = False
print(f"Checking n = {n}")

for i in range(38):
    k = n + i
    s_k = sum_digits(k)

    if s_k % 11 == 0:
        print(f"FAILURE detected at i = {i}. k = {k}. S({k}) = {s_k}. {s_k} is divisible by 11.")
        check_failed = True
        break
    else:
        # Optionally print a few values to monitor progress
        if i < 5 or i > 32:
            print(f"i = {i}: k = {k}, S(k) = {s_k}, S(k) mod 11 = {s_k % 11}")

if not check_failed:
    print(f"\nSUCCESS: For n = {n}, S(n+i) is not a multiple of 11 for all i in {list(range(38))}.")
